<?php $related = kimpu_get_related_posts( get_the_ID(), kimpu_blog_mod( 'related_count', 3 ) ); if ( $related->have_posts() ) : ?><section class="related-posts" aria-labelledby="related-posts-title"><h2 id="related-posts-title"><?php esc_html_e( 'You may also like', 'kimpu-multipurpose' ); ?></h2><div class="related-post-grid related-columns-<?php echo esc_attr( absint( kimpu_blog_mod( 'related_columns', 3 ) ) ); ?>"><?php while ( $related->have_posts() ) : $related->the_post(); kimpu_blog_render_post_item( 'card', 3 ); endwhile; ?></div></section><?php wp_reset_postdata(); endif; ?>
